/** 
// 关于检测组 detectionGroups 编写方式
// 1. 需要在 payloads 中罗列会用到的 payload；如果 payload 中有 " 引号，需在 " 前加转义符，如 \"
// 2. "compareWith": "original" 表示与原始响应比较
//    示例：
//      {
//          "payload": "'",
//          "compareWith": "original",
//          "threshold": 0.989,
//          "thresholdOperator": "<",
//          "timeThreshold": 5000,
//          "timeThresholdOperator": "<"
//      }
//      含义：参数拼接 ' 后，响应与原响应相似度 < 0.989 且响应时间 < 5000ms
//      {
//          "payload": "'''",
//          "compareWith": "'",
//          "threshold": 0.99,
//          "thresholdOperator": ">",
//          "timeThreshold": 5000,
//          "timeThresholdOperator": "<"
//      }
//      含义：''' 与 ' 的响应相似度 > 0.99 且响应时间 < 5000ms
//    不同 {} 条件之间为“同时满足”关系
// 3. 调试时建议先注释去重逻辑（当前位于 mirrorFilteredHTTPFlow 内）
// 4. 敏感关键字列表在载荷测试循环内定义（可自行扩展）
*/

// === CLI 参数定义 ===
blacklistDomainsStr = cli.String("blacklist", cli.setDefault("baidu.com,google.com,googleapis.com"), cli.setHelp("设置域名黑名单，逗号分隔；匹配主域及其子域"), cli.setVerboseName("域名黑名单"), cli.setRequired(false))
paramBlacklistStr = cli.String("param-blacklist", cli.setDefault("name,token,csrf_token,session_id,timestamp,signature"), cli.setHelp("参数名黑名单，这些参数不检测SQL注入"), cli.setVerboseName("参数名黑名单"), cli.setRequired(false))
urlSuffixBlacklistStr = cli.String("url-suffix-blacklist", cli.setDefault(".png,.jpg,.jpeg,.gif,.css,.js,.ico,.svg,.woff,.woff2,.ttf,.eot,.pdf,.zip,.rar,.exe,.mp3,.mp4,.avi"), cli.setHelp("URL后缀黑名单，排除静态资源"), cli.setVerboseName("URL后缀黑名单"), cli.setRequired(false))
pathBlacklistStr = cli.String("path-blacklist", cli.setDefault("/api/status,/health,/ping,/static,/assets,/images,/css,/js,/favicon.ico"), cli.setHelp("路径黑名单，排除特定路径"), cli.setVerboseName("路径黑名单"), cli.setRequired(false))
paramValueBlacklistStr = cli.String("param-value-blacklist", cli.setDefault("true,false,1,0,yes,no,on,off"), cli.setHelp("参数值黑名单，排除常见布尔/标志值"), cli.setVerboseName("参数值黑名单"), cli.setRequired(false))
minParamValueLength = cli.Int("min-param-value-length", cli.setDefault(2), cli.setHelp("最小参数值长度，低于此值不检测"), cli.setVerboseName("最小参数值长度"), cli.setRequired(false))
maxConcurrent = cli.Int("max-concurrent", cli.setDefault(5), cli.setHelp("最大并发请求数"), cli.setVerboseName("最大并发数"), cli.setRequired(false))
similarityThresholdFactor = cli.Float("similarity-threshold-factor", cli.setDefault(1.0), cli.setHelp("相似度阈值调整系数（0.5~2.0）"), cli.setVerboseName("相似度阈值调整系数"), cli.setRequired(false))

cli.check()

// === 工具函数：解析黑名单为 map ===
parseDomainListToMap = func(listStr) {
    m = make(map[string]bool)
    if listStr == nil || listStr == "" { 
        return m 
    }
    items = str.Split(listStr, ",")
    for _, item := range items {
        d = str.TrimSpace(item)
        if d == "" {
            continue
        }
        d = str.ToLower(d)
        if str.HasPrefix(d, ".") {
            d = d[1:]
        }
        if str.HasSuffix(d, ".") {
            d = d[:len(d)-1]
        }
        if d != "" {
            m[d] = true
        }
    }
    return m
}

parseParamListToMap = func(listStr) {
    m = make(map[string]bool)
    if listStr == nil || listStr == "" { 
        return m 
    }
    items = str.Split(listStr, ",")
    for _, item := range items {
        paramName = str.TrimSpace(item)
        if paramName == "" {
            continue
        }
        paramName = str.ToLower(paramName)
        if paramName != "" {
            m[paramName] = true
        }
    }
    return m
}

parseUrlSuffixListToMap = func(listStr) {
    m = make(map[string]bool)
    if listStr == nil || listStr == "" { 
        return m 
    }
    items = str.Split(listStr, ",")
    for _, item := range items {
        suffix = str.TrimSpace(item)
        if suffix == "" {
            continue
        }
        suffix = str.ToLower(suffix)
        if suffix != "" {
            m[suffix] = true
        }
    }
    return m
}

parsePathListToMap = func(listStr) {
    m = make(map[string]bool)
    if listStr == nil || listStr == "" { 
        return m 
    }
    items = str.Split(listStr, ",")
    for _, item := range items {
        path = str.TrimSpace(item)
        if path == "" {
            continue
        }
        path = str.ToLower(path)
        if path != "" {
            m[path] = true
        }
    }
    return m
}

parseParamValueListToMap = func(listStr) {
    m = make(map[string]bool)
    if listStr == nil || listStr == "" { 
        return m 
    }
    items = str.Split(listStr, ",")
    for _, item := range items {
        value = str.TrimSpace(item)
        if value == "" {
            continue
        }
        value = str.ToLower(value)
        if value != "" {
            m[value] = true
        }
    }
    return m
}

// === 初始化黑名单映射 ===
domainBlacklistMap = parseDomainListToMap(blacklistDomainsStr)
paramBlacklistMap = parseParamListToMap(paramBlacklistStr)
