pathBlacklistMap = parsePathListToMap(pathBlacklistStr)
paramValueBlacklistMap = parseParamValueListToMap(paramValueBlacklistStr)

// === 相似度阈值调整函数 ===
adjustThreshold = func(threshold, factor) {
    adjusted = threshold * factor
    if adjusted > 1.0 {
        adjusted = 1.0
    } else if adjusted < 0.0 {
        adjusted = 0.0
    }
    return adjusted
}

// === 主处理函数 ===
mirrorFilteredHTTPFlow = func(isHttps, url, req, rsp, body) {
