    // 检查路径黑名单
    reqPath = poc.GetHTTPRequestPath(req)
    lowerPath = str.ToLower(reqPath)
    for path, _ := range pathBlacklistMap {
        if lowerPath == path || str.HasPrefix(lowerPath, path + "/") {
            println("路径黑名单命中，跳过: " + reqPath + " (路径: " + path + ")")
            return
        }
    }
    
    freq, err = fuzz.HTTPRequest(req, fuzz.https(isHttps))
