    hostLower = str.ToLower(host)
    for domain, _ := range domainBlacklistMap {
        if hostLower == domain || str.HasSuffix(hostLower, "." + domain) {
            println("黑名单命中域名，跳过: " + host)
            return
        }
    }

    getpa = freq.GetCommonParams()
    getpa = string(getpa)
    paths222 = ""

